// @name Minesweeper
// @background #f3f1ec
// @refresh 3600
// Minesweeper for a touch screen or a frame's keys. Tap a square to open it
// (or walk to it with the keys and press OK), switch to Flag to mark a mine
// (or hold a square on a fast screen), and open an open number whose mines
// are all flagged to open the rest around it. The first square opened is
// never a mine. The game in progress and the best times are kept.
import { newGame, reveal, chord, toggleFlag, numbers, flagCount } from './logic'
import { highContrast, inkPaper, canvasOf, clamp, fitWidth, Button, OptionsPage, Title, roundRoom, RimButton, SlidersGlyph } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f3f1ec] text-[#1f2933]',
    muted: 'text-[#5d6873]',
    button: 'bg-[#e3dfd5] text-[#1f2933] active:bg-[#d5cfc1]',
    primary: 'bg-[#34495e] text-white active:bg-[#44607a]',
    on: 'bg-[#34495e] text-white',
    off: 'bg-[#e3dfd5] text-[#1f2933]',
    frame: '#34495e',
    tile: '#6f8799',
    tileEdge: '#5a7183',
    open: '#ebe7de',
    grid: '#d2cbbd',
    numbers: ['', '#2b5f9e', '#2e7d4f', '#b8432f', '#4b3a8c', '#8a3324', '#1f7a7a', '#222222', '#6b6b6b'],
    flag: '#c8553d',
    pole: '#ffffff',
    mine: '#1f2933',
    shine: '#ffffff',
    boom: '#e07a5f',
    wrong: '#ffffff',
    icon: 'text-[#34495e]',
    // The square the keys are on: a frame inside it, light on a tile, dark on an open square.
    onTile: '#ffffff',
    onOpen: '#1f2933',
  },
  // Colour e-paper: the six inks alone, white paper, blue tiles.
  ink: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-[#0033cc] text-white',
    on: 'bg-[#0033cc] text-white',
    off: 'bg-white text-black border-2 border-black',
    frame: '#000000',
    tile: '#0033cc',
    tileEdge: '#0033cc',
    open: '#ffffff',
    grid: '#000000',
    numbers: ['', '#0033cc', '#006b2e', '#cc0000', '#000000', '#cc0000', '#006b2e', '#000000', '#000000'],
    flag: '#ffff00',
    pole: '#ffffff',
    mine: '#000000',
    shine: '#ffffff',
    boom: '#cc0000',
    wrong: '#ffffff',
    icon: 'text-black',
    onTile: '#ffff00',
    onOpen: '#000000',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    frame: '#000000',
    tile: '#000000',
    tileEdge: '#000000',
    open: '#ffffff',
    grid: '#000000',
    numbers: ['', '#000000', '#000000', '#000000', '#000000', '#000000', '#000000', '#000000', '#000000'],
    flag: '#ffffff',
    pole: '#ffffff',
    mine: '#000000',
    shine: '#ffffff',
    boom: '#000000',
    wrong: '#ffffff',
    icon: 'text-black',
    onTile: '#ffffff',
    onOpen: '#000000',
  },
}

const LEVELS = {
  beginner: { name: 'Beginner', cols: 9, rows: 9, mines: 10 },
  intermediate: { name: 'Intermediate', cols: 16, rows: 16, mines: 40 },
  expert: { name: 'Expert', cols: 0, rows: 0, mines: 0 },
  custom: { name: 'Custom', cols: 0, rows: 0, mines: 0 },
}

const settingsOf = (app) => {
  const level = LEVELS[app.state.difficulty] ? app.state.difficulty : 'beginner'
  const cols = clamp(Math.round(Number(app.state.customColumns) || 12), 5, 30)
  const rows = clamp(Math.round(Number(app.state.customRows) || 10), 5, 24)
  const mines = clamp(Math.round(Number(app.state.customMines) || 20), 1, cols * rows - 9)
  return { level, cols, rows, mines }
}

// What a game was made from: a game whose key no longer matches the settings
// gives way to a new one. Expert's size comes from the screen when it starts,
// so a window of another size keeps the game.
const keyOf = (s) => (s.level === 'custom' ? `custom:${s.cols}x${s.rows}:${s.mines}` : s.level)

// The game in progress, kept in the scene's private `game` field.
type Kept = any
const loadGame = (app): Kept | null => {
  const g = app.state.game
  return g && typeof g.cells === 'string' && g.cols > 0 && g.cells.length === g.cols * g.rows ? g : null
}
const save = (game) => frameos.setState('game', game)

// Expert fills the board's area with squares a finger can still hit, about
// a fifth of them mines (the classic 99 of 480).
const expertSize = (areaW: number, areaH: number, short: number) => {
  const cell = Math.max(30, short / 16)
  const cols = clamp(Math.floor(areaW / cell), 9, 30)
  const rows = clamp(Math.floor(areaH / cell), 9, 24)
  return { cols, rows, mines: Math.round(cols * rows * 0.206) }
}

const formatTime = (ms: number) => {
  const s = Math.max(0, Math.round(ms / 1000))
  return s >= 3600 ? `${Math.floor(s / 3600)}:${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}` : `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

// What each square shows, one signal a square, and the panel's lines: a tap
// runs only the squares and lines that read what it changed, not get(). The
// game itself stays in the scene's `game` field.
let looks = []
const left = signal(0)
const headline = signal('')
const detail = signal('')
const flagMode = signal(false)

// A square's look: "T" a tile, "F" a flag, "X" a wrong flag, "M" a mine shown
// when the game is lost, "B" the mine that went off, "1"-"8" a number, "" open.
const lookOf = (game, nums, i: number) => {
  const cell = game.cells[i]
  const mine = game.layout[i] === '1'
  const over = game.state === 'lost'
  if (cell === '1') return i === game.boom ? 'B' : nums[i] ? String(nums[i]) : ''
  if (over && mine && cell === '0') return 'M'
  if (cell === '2') return over && !mine ? 'X' : 'F'
  return 'T'
}

// Every signal from the game, the flag mode and the best times.
const show = (app, game) => {
  if (looks.length !== game.cells.length) looks = Array.from({ length: game.cells.length }, () => signal(''))
  const nums = numbers(game)
  for (let i = 0; i < game.cells.length; i++) looks[i].value = lookOf(game, nums, i)
  left.value = game.mines - flagCount(game)
  const flag = !!frameos.recall('flag')
  flagMode.value = flag
  const best = app.state.best && typeof app.state.best === 'object' ? app.state.best[game.key] : 0
  let h = ''
  let d = ''
  if (game.state === 'won') {
    h = 'Cleared!'
    d = `${formatTime(game.ended - game.started)}${frameos.recall('record') ? ', a new best' : best ? ` (best ${formatTime(best)})` : ''}`
  } else if (game.state === 'lost') {
    h = 'Boom!'
    d = 'That one was a mine.'
  } else if (game.state === 'ready') {
    d = 'Pick any square to start'
  } else if (flag) {
    d = 'Picking a square flags it'
  }
  headline.value = h
  detail.value = d
}

// A tap on square `i`: open it (or flag it in flag mode); on an open number,
// open its neighbours when its flags are placed. A tap that ends the game
// sets no signal: get() draws it whole (every mine, the buttons that change).
const tapCell = (app, i: number, flag: boolean) => {
  const game = loadGame(app)
  if (!game || i < 0 || i >= game.cells.length) return
  const now = Date.now()
  if (game.cells[i] === '1') chord(game, i, Math.random, now)
  else if (flag) toggleFlag(game, i)
  else if (game.cells[i] === '0') reveal(game, i, Math.random, now)
  else return
  if (game.state === 'won') recordBest(app, game)
  save(game)
  if (game.state !== 'won' && game.state !== 'lost') show(app, game)
}

const recordBest = (app, game: Kept) => {
  const best = app.state.best && typeof app.state.best === 'object' ? { ...app.state.best } : {}
  const time = game.ended - game.started
  if (!best[game.key] || time < best[game.key]) {
    best[game.key] = time
    frameos.setState('best', best)
    frameos.remember('record', true)
  } else frameos.remember('record', false)
}

const restart = () => {
  save({ cols: 0 })
  frameos.remember('page', null)
  frameos.remember('flag', false)
}

const toggleMode = () => frameos.remember('flag', !frameos.recall('flag'))

// The Open / Flag buttons: the mode and the line that says it.
const setMode = (app, flag: boolean) => {
  frameos.remember('flag', flag)
  const game = loadGame(app)
  if (game) show(app, game)
}

// The frame's back leaves the options page, forward is a new game once this
// one is over (a swipe or a Back key is no move of the game: the Flag button
// and a long press flag). N and F on a keyboard: a new game, open or flag.
export function onEvent(app, context) {
  const event = context.event
  const options = frameos.recall('page') === 'options'
  if (event === 'back') {
    if (!options) return false
    frameos.remember('page', null)
  } else if (event === 'forward') {
    const game = loadGame(app)
    if (options || !game || (game.state !== 'won' && game.state !== 'lost')) return false
    restart()
  } else if (event === 'keyDown') {
    const p = context.payload || {}
    const key = String(p.key || '').toLowerCase()
    if (p.ctrl || p.alt || p.meta) return false
    if (key === 'n') restart()
    else if (key === 'f') toggleMode()
    else return false
  } else return false
  return true
}

// The pictures inside a square, 100 units across.
const Flag = ({ x, y, t }) => (
  <g>
    <line x1={x + 38} y1={y + 22} x2={x + 38} y2={y + 76} stroke={t.pole} strokeWidth={7} strokeLinecap="round" />
    <polygon points={`${x + 41},${y + 20} ${x + 76},${y + 36} ${x + 41},${y + 52}`} fill={t.flag} />
    <rect x={x + 24} y={y + 72} width={30} height={8} rx={3} fill={t.pole} />
  </g>
)
const Mine = ({ x, y, fill, shine }) => (
  <g>
    <line x1={x + 50} y1={y + 16} x2={x + 50} y2={y + 84} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <line x1={x + 16} y1={y + 50} x2={x + 84} y2={y + 50} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <line x1={x + 26} y1={y + 26} x2={x + 74} y2={y + 74} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <line x1={x + 74} y1={y + 26} x2={x + 26} y2={y + 74} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <circle cx={x + 50} cy={y + 50} r={24} fill={fill} />
    <circle cx={x + 42} cy={y + 42} r={7} fill={shine} />
  </g>
)

// One square, drawn from its look.
const Cell = memo(({ i, cols, t, high }) => {
  const look = looks[i].value
  const x = (i % cols) * 100
  const y = Math.floor(i / cols) * 100
  if (look === 'B') {
    return (
      <g>
        <rect x={x} y={y} width={100} height={100} fill={t.boom} />
        <Mine x={x} y={y} fill={high ? '#ffffff' : t.mine} shine={high ? '#000000' : t.shine} />
      </g>
    )
  }
  if (look === '') return <g />
  if (look !== 'T' && look !== 'F' && look !== 'X' && look !== 'M') {
    return (
      <g>
        <text x={x + 50} y={y + 73} fontSize={64} fontWeight="bold" textAnchor="middle" fill={t.numbers[Number(look)]}>
          {look}
        </text>
      </g>
    )
  }
  // A lost game shows every mine, and crosses out the flags that were wrong.
  if (look === 'M') return <g><Mine x={x} y={y} fill={t.mine} shine={t.shine} /></g>
  return (
    <g>
      <rect x={x + 5} y={y + 5} width={90} height={90} rx={12} fill={t.tile} stroke={t.tileEdge} strokeWidth={3} />
      {look === 'F' || look === 'X' ? <Flag x={x} y={y} t={t} /> : null}
      {look === 'X' ? <line x1={x + 18} y1={y + 18} x2={x + 82} y2={y + 82} stroke={t.wrong} strokeWidth={9} strokeLinecap="round" /> : null}
      {look === 'X' ? <line x1={x + 82} y1={y + 18} x2={x + 18} y2={y + 82} stroke={t.wrong} strokeWidth={9} strokeLinecap="round" /> : null}
    </g>
  )
})

const Board = ({ t, game, high, width, height }) => {
  const { cols, rows } = game
  const parts = []
  for (let c = 1; c < cols; c++) parts.push(<line x1={c * 100} y1={0} x2={c * 100} y2={rows * 100} stroke={t.grid} strokeWidth={high ? 3 : 4} />)
  for (let r = 1; r < rows; r++) parts.push(<line x1={0} y1={r * 100} x2={cols * 100} y2={r * 100} stroke={t.grid} strokeWidth={high ? 3 : 4} />)
  for (let i = 0; i < game.cells.length; i++) parts.push(<Cell i={i} cols={cols} t={t} high={high} />)
  return (
    <svg viewBox={`-8 -8 ${cols * 100 + 16} ${rows * 100 + 16}`} width={width} height={height}>
      <rect x={-6} y={-6} width={cols * 100 + 12} height={rows * 100 + 12} rx={10} fill={t.frame} />
      <rect x={0} y={0} width={cols * 100} height={rows * 100} fill={t.open} />
      {parts}
    </svg>
  )
}

// Each square is an element of its own over the drawing, row by row: a tap
// opens it (or flags it, held), and a frame's keys walk the squares (the
// frame drawn in the square the keys are on is the cursor) and OK opens one.
const Hit = memo(({ i, x, y, w, h, t, app }) => {
  const look = looks[i].value
  const lit = look === 'T' || look === 'F' || look === 'X' ? t.onTile : t.onOpen
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px] rounded-[${Math.round(w * 0.14)}px] focus:border-[${Math.max(2, Math.round(w * 0.12))}px] focus:border-[${lit}]`}
      onClick={() => tapCell(app, i, flagMode.peek())}
      onLongPress={() => tapCell(app, i, !flagMode.peek())} />
  )
})
const Hits = ({ game, t, app, width, height }) => {
  const sx = width / (game.cols * 100 + 16)
  const sy = height / (game.rows * 100 + 16)
  const xs = []
  const ys = []
  for (let c = 0; c <= game.cols; c++) xs.push(Math.round((8 + c * 100) * sx))
  for (let r = 0; r <= game.rows; r++) ys.push(Math.round((8 + r * 100) * sy))
  const hits = []
  for (let i = 0; i < game.cells.length; i++) {
    const c = i % game.cols
    const r = Math.floor(i / game.cols)
    hits.push(<Hit i={i} x={xs[c]} y={ys[r]} w={xs[c + 1] - xs[c]} h={ys[r + 1] - ys[r]} t={t} app={app} />)
  }
  return hits
}

const MineIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <line x1={12} y1={2} x2={12} y2={22} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <line x1={2} y1={12} x2={22} y2={12} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <line x1={5} y1={5} x2={19} y2={19} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <line x1={19} y1={5} x2={5} y2={19} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <circle cx={12} cy={12} r={7} fill="currentColor" />
  </svg>
)
const FlagIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <path d="M6 2h2v18h3v2H3v-2h3zM9 3l10 4.5L9 12z" fill="currentColor" />
  </svg>
)

// The panel's parts that a tap changes, each reading its signals.
const Counter = memo(({ ui, t }) => {
  const iconSize = Math.round(ui.big * 1.1)
  return (
    <div className={`flex items-center gap-[${Math.round(ui.gap * 0.6)}px]`}>
      <MineIcon className={`w-[${iconSize}px] h-[${iconSize}px] ${t.icon}`} />
      <span className={`text-[${Math.round(ui.big * 1.15)}px] font-bold`}>{String(left.value)}</span>
    </div>
  )
})
const Result = ({ ui, t }) => (
  <div className="flex flex-col">
    {headline.value ? <span className={`text-[${ui.big}px] font-bold leading-tight`}>{headline.value}</span> : null}
    {detail.value ? <span className={`text-[${ui.small}px] ${t.muted}`}>{detail.value}</span> : null}
  </div>
)
const SideResult = memo(Result)
// On a tall screen the level's name stands where there is nothing to say.
const TallResult = memo(({ ui, t, levelName }) => (
  <div className="flex-1 min-w-0">{headline.value || detail.value ? <Result ui={ui} t={t} /> : <span className={`text-[${ui.small}px] ${t.muted}`}>{levelName}</span>}</div>
))
const OpenButton = memo(({ ui, t, app }) => (
  <Button ui={ui} grow className={flagMode.value ? t.off : t.on} onClick={() => setMode(app, false)}>
    Open
  </Button>
))
// Flag, with its glyph where there is room for both.
const FlagButton = memo(({ ui, t, app, bare }) => {
  const modeIcon = Math.round(ui.text * 1.1)
  return (
    <Button ui={ui} grow className={flagMode.value ? t.on : t.off} onClick={() => setMode(app, true)}>
      {bare ? <span>Flag</span> : (
        <div className="flex items-center gap-[6px]">
          <FlagIcon className={`w-[${modeIcon}px] h-[${modeIcon}px]`} />
          <span>Flag</span>
        </div>
      )}
    </Button>
  )
})
// Where the bar has no room for both words (a watch): one key with the flag's
// glyph, lit while picking a square flags it.
const FlagToggle = memo(({ ui, t, app }) => {
  const modeIcon = Math.round(ui.text * 1.3)
  return (
    <div className={`w-[${ui.button}px] h-[${ui.button}px] shrink-0 rounded-xl flex items-center justify-center ${flagMode.value ? t.on : t.off}`}
      onClick={() => setMode(app, !flagMode.peek())}>
      <FlagIcon className={`w-[${modeIcon}px] h-[${modeIcon}px]`} />
    </div>
  )
})

// On a round panel: Open and Flag in the arc below the board, as wide as the circle there.
const RoundModes = memo(({ w, h, size, gap, t, app }) => {
  const bw = Math.floor((w - gap) / 2)
  const icon = Math.round(size * 1.1)
  return (
    <div className={`flex gap-[${gap}px]`}>
      <div className={`w-[${bw}px] h-[${h}px] rounded-xl flex items-center justify-center text-[${size}px] font-semibold ${flagMode.value ? t.off : t.on}`}
        onClick={() => setMode(app, false)}>
        Open
      </div>
      <div className={`w-[${bw}px] h-[${h}px] rounded-xl flex items-center justify-center gap-[6px] text-[${size}px] font-semibold ${flagMode.value ? t.on : t.off}`}
        onClick={() => setMode(app, true)}>
        <FlagIcon className={`w-[${icon}px] h-[${icon}px]`} />
        <span>Flag</span>
      </div>
    </div>
  )
})
// The result in their place once the game is over, centred.
const RoundResult = memo(({ w, size, small, t }) => (
  <div className={`w-[${w}px] flex flex-col items-center`}>
    {headline.value ? <span className={`text-[${size}px] font-bold leading-tight`}>{headline.value}</span> : null}
    {detail.value ? <span className={`text-[${small}px] text-center leading-tight ${t.muted}`}>{detail.value}</span> : null}
  </div>
))

// The sizes only change with the canvas: the same object while it does not,
// so the memo()'d parts are not run again for a new one.
let lastUi = null
const stableUi = (ui) => (lastUi && lastUi.W === ui.W && lastUi.H === ui.H ? lastUi : (lastUi = ui))

// The options button where there is no room for its word.
const SlidersIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <line x1={3} y1={6} x2={21} y2={6} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <line x1={3} y1={12} x2={21} y2={12} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <line x1={3} y1={18} x2={21} y2={18} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <circle cx={8} cy={6} r={2.6} fill="currentColor" />
    <circle cx={16} cy={12} r={2.6} fill="currentColor" />
    <circle cx={10} cy={18} r={2.6} fill="currentColor" />
  </svg>
)

export function get(app, context) {
  const ui = stableUi(canvasOf(app, context))
  const high = highContrast(app)
  const t = high ? THEMES.high : inkPaper(app) ? THEMES.ink : THEMES.color
  const settings = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows: any[] = [
      { field: 'difficulty', label: 'Difficulty', value: settings.level,
        options: [['beginner', 'Beginner'], ['intermediate', 'Intermediate'], ['expert', 'Expert'], ['custom', 'Custom']] },
    ]
    if (settings.level === 'custom') {
      rows.push({ field: 'customColumns', label: 'Columns', value: settings.cols, min: 5, max: 30 })
      rows.push({ field: 'customRows', label: 'Rows', value: settings.rows, min: 5, max: 24 })
      rows.push({ field: 'customMines', label: 'Mines', value: settings.mines, min: 1, max: settings.cols * settings.rows - 9, step: 5 })
    }
    return <OptionsPage ui={ui} t={t} title="Minesweeper" rows={rows}
      onClose={() => frameos.remember('page', null)} onNew={restart} />
  }

  // Side by side on a wide screen; on a tall one a bar above the board and
  // one below; on a square one everything in the bar below.
  // Round: the board in the square inside the circle (a little shorter, so
  // the buttons below it sit where the circle is wider), the mines left in
  // the arc above between New and the options on the rim, Open and Flag in
  // the arc below.
  const room = ui.round ? roundRoom(ui.W, ui.H) : null
  const side = !room && ui.W >= ui.H * 1.15
  const tall = !room && !side && ui.H > ui.W * 1.25
  const sideW = Math.round(Math.max(ui.W * 0.26, ui.text * 9))
  const areaW = room ? room.side : side ? ui.W - sideW - ui.pad * 3 : ui.W - ui.pad * 2
  const areaH = room ? room.side - Math.round(ui.button * 0.5) : side ? ui.H - ui.pad * 2 : ui.H - ui.pad * 2 - (ui.gap + ui.button) * (tall ? 2 : 1)

  // A new game when there is none or the settings changed.
  const key = keyOf(settings)
  let game = loadGame(app)
  if (!game || game.key !== key) {
    const size = settings.level === 'custom' ? settings
      : settings.level === 'expert' ? expertSize(areaW, areaH, Math.min(ui.W, ui.H))
      : LEVELS[settings.level]
    game = { ...newGame(size.cols, size.rows, size.mines), key }
    save(game)
    frameos.remember('flag', false)
  }

  show(app, game)
  const cell = Math.floor(Math.min(areaW / (game.cols + 0.16), areaH / (game.rows + 0.16)))
  const boardW = Math.round(cell * (game.cols + 0.16))
  const boardH = Math.round(cell * (game.rows + 0.16))
  const board = (
    <div className={`relative w-[${boardW}px] h-[${boardH}px] shrink-0`}>
      <Board t={t} game={game} high={high} width={boardW} height={boardH} />
      <Hits game={game} t={t} app={app} width={boardW} height={boardH} />
    </div>
  )

  const levelName = `${LEVELS[settings.level].name} · ${game.cols}×${game.rows}`
  const counter = <Counter ui={ui} t={t} />
  // Made only where they are drawn: a component made runs at once, and one
  // that reads a signal but is not drawn turns the next tap into a whole get().
  const modeButtons = () => [<OpenButton ui={ui} t={t} app={app} />, <FlagButton ui={ui} t={t} app={app} />]
  // Only a whole get() ends a game or starts one, so what changes with that
  // (the New button, the result in place of Open / Flag) is drawn here.
  const over = game.state === 'won' || game.state === 'lost'
  const newButton = <Button ui={ui} grow className={over ? t.primary : t.button} onClick={restart}>New</Button>
  const openOptions = () => frameos.remember('page', 'options')
  const gap = Math.round(ui.gap * 0.6)

  if (room) {
    const { chord, rimSpot } = room
    const top = (ui.H - boardH) >> 1
    const d = Math.max(40, Math.round(ui.button * 0.86))
    const [nx, ny] = rimSpot(d, boardH, true)
    const [ox, oy] = rimSpot(d, boardH, false)
    const bh = Math.max(40, Math.min(ui.button, Math.round(top * 0.5)))
    const bTop = top + boardH + 8
    const pairW = Math.min(chord(bTop + bh - ui.H / 2), Math.round(ui.W * 0.6))
    const size = Math.max(14, Math.min(ui.text, Math.round(bh * 0.4)))
    return (
      <div className={`relative w-[${ui.W}px] h-[${ui.H}px] ${t.page}`}>
        <div className={`absolute left-0 top-0 w-[${ui.W}px] h-[${top - 6}px] flex items-end justify-center`}>{counter}</div>
        <div className={`absolute left-[${(ui.W - boardW) >> 1}px] top-[${top}px]`}>{board}</div>
        <div className={`absolute left-0 top-[${bTop}px] w-[${ui.W}px] flex justify-center`}>
          {over ? <RoundResult w={pairW} size={Math.max(16, Math.min(ui.big, Math.round(bh * 0.5)))} small={Math.max(14, Math.min(ui.small, Math.round(bh * 0.34)))} t={t} />
            : <RoundModes w={pairW} h={bh} size={size} gap={gap} t={t} app={app} />}
        </div>
        <RimButton x={nx} y={ui.H - ny - d} d={d} className={over ? t.primary : t.button} onClick={restart}>
          <span className={`text-[${Math.max(14, Math.round(d * 0.32))}px] font-semibold`}>New</span>
        </RimButton>
        <RimButton x={ox} y={ui.H - oy - d} d={d} className={t.button} onClick={openOptions}>
          <SlidersGlyph px={Math.round(d * 0.5)} />
        </RimButton>
      </div>
    )
  }

  if (side) {
    // Two buttons a row: the options' word where half the column holds it,
    // else its glyph, and Flag's glyph only where there is room beside it.
    const half = (sideW - gap) / 2
    const optionsWord = fitWidth('Options', ui.text) <= half
    const flagBare = fitWidth('Flag', ui.text) + ui.text * 1.1 + 6 > half
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        <div className="flex-1 h-full flex items-center justify-center">{board}</div>
        <div className={`w-[${sideW}px] h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={sideW}>Minesweeper</Title>
          <span className={`text-[${ui.small}px] ${t.muted}`}>{levelName}</span>
          {counter}
          <SideResult ui={ui} t={t} />
          <div className="flex-1" />
          <div className={`flex gap-[${gap}px]`}>
            <OpenButton ui={ui} t={t} app={app} />
            <FlagButton ui={ui} t={t} app={app} bare={flagBare} />
          </div>
          <div className={`flex gap-[${gap}px]`}>
            {newButton}
            {optionsWord ? <Button ui={ui} grow className={t.button} onClick={openOptions}>Options</Button>
              : <Button ui={ui} className={`w-[${ui.button}px] ${t.button}`} onClick={openOptions}>
                <SlidersIcon className={`w-[${Math.round(ui.text * 1.3)}px] h-[${Math.round(ui.text * 1.3)}px]`} />
              </Button>}
          </div>
        </div>
      </div>
    )
  }
  if (tall) {
    return (
      <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
        <div className={`flex items-center gap-[${ui.gap * 2}px] h-[${ui.button}px]`}>
          {counter}
          <TallResult ui={ui} t={t} levelName={levelName} />
        </div>
        <div className="flex-1 flex items-center justify-center">{board}</div>
        <div className={`flex gap-[${gap}px]`}>
          {modeButtons()}
          {newButton}
          <Button ui={ui} grow className={t.button} onClick={openOptions}>Options</Button>
        </div>
      </div>
    )
  }
  // Square: the counter, then the result once the game is over (else the
  // Open / Flag pair, or on a bar too narrow for both words the flag's key),
  // a new game and the options as an icon.
  const sliders = Math.round(ui.text * 1.3)
  const counterW = Math.round(ui.big * 1.1) + Math.round(ui.gap * 0.6) + ui.big * 1.15 * 0.62 * String(game.mines).length + gap
  const pairW = fitWidth('Open', ui.text) + fitWidth('Flag', ui.text) + ui.text * 1.1 + 6
  const narrow = counterW + pairW + fitWidth('New', ui.text) + ui.button + gap * 4 > ui.W - ui.pad * 2
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <div className={`flex items-center gap-[${gap}px]`}>
        <div className={`pr-[${gap}px]`}>{counter}</div>
        {over ? <div className="flex-1 min-w-0"><SideResult ui={ui} t={t} /></div> : narrow ? <FlagToggle ui={ui} t={t} app={app} /> : modeButtons()}
        {newButton}
        <Button ui={ui} className={`w-[${ui.button}px] ${t.button}`} onClick={openOptions}>
          <SlidersIcon className={`w-[${sliders}px] h-[${sliders}px]`} />
        </Button>
      </div>
    </div>
  )
}

