// Minesweeper's rules. Pure: no frameos calls, so it can be checked with
// plain node.
//
// A game is a plain object kept in scene state:
//   cols, rows, mines   the board's size and how many mines it hides
//   layout              one character a cell, "1" a mine ("" until the first
//                       tap, which places them away from it)
//   cells               one character a cell: "0" hidden, "1" open, "2" flagged
//   state               "ready" (no tap yet), "play", "won" or "lost"
//   boom                the mine that went off, or -1
//   started, ended      when the first tap and the end came (ms)

export type Game = {
  cols: number
  rows: number
  mines: number
  layout: string
  cells: string
  state: string
  boom: number
  started: number
  ended: number
}

export function newGame(cols: number, rows: number, mines: number): Game {
  const n = cols * rows
  return {
    cols,
    rows,
    mines: Math.max(1, Math.min(mines, n - 1)),
    layout: '',
    cells: '0'.repeat(n),
    state: 'ready',
    boom: -1,
    started: 0,
    ended: 0,
  }
}

// The cells around cell `i` (up to eight).
export function neighbours(game: Game, i: number) {
  const { cols, rows } = game
  const x = i % cols
  const y = (i - x) / cols
  const out: number[] = []
  for (let dy = -1; dy <= 1; dy++) {
    const ny = y + dy
    if (ny < 0 || ny >= rows) continue
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx
      if ((dx || dy) && nx >= 0 && nx < cols) out.push(ny * cols + nx)
    }
  }
  return out
}

// How many mines touch each cell.
export function numbers(game: Game) {
  const n = game.cols * game.rows
  const out = new Int8Array(n)
  if (!game.layout) return out
  for (let i = 0; i < n; i++) {
    if (game.layout[i] !== '1') continue
    for (const j of neighbours(game, i)) out[j]++
  }
  return out
}

// Hides the mines anywhere but the first cell tapped and, where the board
// has room, its neighbours too, so the first tap always opens an area.
function placeMines(game: Game, first: number, random: () => number) {
  const n = game.cols * game.rows
  const keep = new Set([first])
  if (n - game.mines >= 9) for (const j of neighbours(game, first)) keep.add(j)
  const free: number[] = []
  for (let i = 0; i < n; i++) if (!keep.has(i)) free.push(i)
  const layout = new Array(n).fill('0')
  for (let k = 0; k < game.mines && free.length; k++) {
    const pick = Math.floor(random() * free.length)
    layout[free[pick]] = '1'
    free[pick] = free[free.length - 1]
    free.pop()
  }
  game.layout = layout.join('')
}

// Opens cell `i`: a mine ends the game, a 0 opens everything around it, and
// so on outwards. Mutates `game`.
export function reveal(game: Game, i: number, random: () => number, now: number) {
  if (game.state === 'won' || game.state === 'lost') return
  if (game.state === 'ready') {
    placeMines(game, i, random)
    game.state = 'play'
    game.started = now
  }
  if (game.cells[i] !== '0') return
  const cells = game.cells.split('')
  if (game.layout[i] === '1') {
    cells[i] = '1'
    game.cells = cells.join('')
    game.state = 'lost'
    game.boom = i
    game.ended = now
    return
  }
  const nums = numbers(game)
  const stack = [i]
  while (stack.length) {
    const c = stack.pop() as number
    if (cells[c] !== '0') continue
    cells[c] = '1'
    if (nums[c] === 0) for (const j of neighbours(game, c)) if (cells[j] === '0') stack.push(j)
  }
  game.cells = cells.join('')
  checkWon(game, now)
}

// Tapping an open number whose flags are all placed opens the rest of its
// neighbours (a "chord"). Answers whether it did anything.
export function chord(game: Game, i: number, random: () => number, now: number) {
  if (game.state !== 'play' || game.cells[i] !== '1') return false
  const nums = numbers(game)
  const around = neighbours(game, i)
  const flags = around.filter((j) => game.cells[j] === '2').length
  const hidden = around.filter((j) => game.cells[j] === '0')
  if (!nums[i] || flags !== nums[i] || !hidden.length) return false
  for (const j of hidden) {
    reveal(game, j, random, now)
    if (game.state === 'lost') break
  }
  return true
}

export function toggleFlag(game: Game, i: number) {
  if (game.state === 'won' || game.state === 'lost') return
  const c = game.cells[i]
  if (c === '1') return
  game.cells = game.cells.slice(0, i) + (c === '2' ? '0' : '2') + game.cells.slice(i + 1)
}

function checkWon(game: Game, now: number) {
  let open = 0
  for (let i = 0; i < game.cells.length; i++) if (game.cells[i] === '1') open++
  if (open !== game.cells.length - game.mines) return
  game.state = 'won'
  game.ended = now
  // Every mine gets its flag.
  let cells = ''
  for (let i = 0; i < game.cells.length; i++) cells += game.layout[i] === '1' ? '2' : game.cells[i]
  game.cells = cells
}

export function flagCount(game: Game) {
  let n = 0
  for (let i = 0; i < game.cells.length; i++) if (game.cells[i] === '2') n++
  return n
}

