// The parts every game here shares: the contrast rule, the canvas's size,
// buttons and the options page. Each game carries its own copy of this file.

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
export const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Solid inks where the panel is colour e-paper (a Spectra's six inks), when
// the Contrast setting is Auto: no greys or pastels, which it dithers into
// confetti.
export const inkPaper = (app) => (app.state.contrast || 'auto') === 'auto' && app.frame.paper === true && app.frame.color !== false

export const clamp = (n: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, n))

// How wide a word is at `size` px: the buttons' words as wide as Ubuntu Bold
// sets them, anything else at about 0.62 of the size a letter; and how wide a
// Button holding it is at the least (its padding is half the size a side).
const EM = { Open: 2.6, Flag: 2.0, New: 2.12, Options: 3.81, 'New game': 4.96 }
export const wordsW = (text: string, size: number) => (EM[text] ?? String(text).length * 0.62) * size
export const fitWidth = (text: string, size: number) => (wordsW(text, 1) + 1) * size

// The canvas being drawn on (already turned with the frame) and the sizes of
// the text and buttons, worked out from its shorter side so the same scene
// reads well on a 480x480 square and on a 1600x1200 panel.
export const canvasOf = (app, context) => {
  const W = Math.round(context?.imageWidth ?? app.frame.width)
  const H = Math.round(context?.imageHeight ?? app.frame.height)
  const short = Math.min(W, H)
  const unit = short / 100
  return {
    W,
    H,
    portrait: H > W * 1.05,
    // A round panel, drawn whole: only the circle inside the square shows.
    round: context?.round === true,
    pad: Math.round(clamp(unit * 3.5, 10, 48)),
    gap: Math.round(clamp(unit * 2, 6, 24)),
    title: Math.round(clamp(unit * 7, 24, 72)),
    big: Math.round(clamp(unit * 5.6, 20, 60)),
    text: Math.round(clamp(unit * 4.4, 16, 44)),
    small: Math.round(clamp(unit * 3.4, 13, 34)),
    button: Math.round(clamp(unit * 11, 44, 110)),
  }
}

// A button: a box with an onClick, at least a finger tall.
export const Button = ({ ui, className, onClick, children, grow }: any) => (
  <div
    className={`${grow ? 'flex-1 basis-0 min-w-0' : ''} h-[${ui.button}px] px-[${Math.round(ui.text * 0.5)}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${ui.text}px] font-semibold ${className}`}
    onClick={onClick}
  >
    {children}
  </div>
)

// One setting as a row of buttons, the chosen one lit. `options` is a list
// of [value, label]. In the narrow square of a round panel, more than three
// go two to a row.
export const Choice = ({ ui, t, label, value, options, onPick }: any) => (
  <div className="flex flex-col gap-1">
    <span className={`text-[${ui.small}px] ${t.muted}`}>{label}</span>
    <div className={`flex ${ui.round && options.length > 3 ? 'flex-wrap' : ''} gap-[${Math.round(ui.gap * 0.7)}px]`}>
      {options.map(([v, text]) => (
        <div
          className={`${ui.round && options.length > 3 ? `w-[${Math.floor((roundRoom(ui.W, ui.H).side - Math.round(ui.gap * 0.7)) / 2)}px]` : 'flex-1'} h-[${Math.round(ui.button * 0.85)}px] rounded-xl flex items-center justify-center text-[${ui.small}px] font-semibold ${String(v) === String(value) ? t.on : t.off}`}
          onClick={() => onPick(v)}
        >
          {text}
        </div>
      ))}
    </div>
  </div>
)

// A number setting: minus, the value, plus.
export const Stepper = ({ ui, t, label, value, min, max, step, onPick }: any) => {
  const h = Math.round(ui.button * 0.85)
  const key = (text: string, next: number) => (
    <div
      className={`w-[${Math.round(h * 1.4)}px] h-[${h}px] rounded-xl flex items-center justify-center text-[${ui.big}px] font-bold ${t.off}`}
      onClick={() => onPick(clamp(next, min, max))}
    >
      {text}
    </div>
  )
  return (
    <div className={`flex items-center gap-[${ui.gap}px]`}>
      <span className={`flex-1 text-[${ui.text}px]`}>{label}</span>
      {key('−', value - (step || 1))}
      <span className={`w-[${Math.round(ui.text * 2.6)}px] text-center text-[${ui.text}px] font-bold`}>{String(value)}</span>
      {key('+', value + (step || 1))}
    </div>
  )
}

// The options page: the game's settings as rows of buttons, written to the
// scene's public fields (the same ones the frame's settings show), and a
// button to start a new game with them. A row with `min` is a number.
export const OptionsPage = ({ ui, t, title, rows, onClose, onNew }: any) => ui.round ? (
  <RoundOptionsPage ui={ui} t={t} title={title} rows={rows} onClose={onClose} onNew={onNew} />
) : (
  <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
    <div className="flex items-center justify-between">
      <span className={`text-[${ui.title}px] font-bold`}>{title}</span>
    </div>
    <div className="flex-1 overflow-y-auto">
      <div className={`flex flex-col gap-[${ui.gap}px]`}>
        {rows.map((row) =>
          row.min !== undefined ? (
            <Stepper ui={ui} t={t} label={row.label} value={row.value} min={row.min} max={row.max} step={row.step}
              onPick={(v) => frameos.setState(row.field, v)} />
          ) : (
            <Choice ui={ui} t={t} label={row.label} value={row.value} options={row.options}
              onPick={(v) => frameos.setState(row.field, v)} />
          ),
        )}
      </div>
    </div>
    <div className={`flex gap-[${ui.gap}px]`}>
      <Button ui={ui} grow className={t.button} onClick={onClose}>Back</Button>
      <Button ui={ui} grow className={t.primary} onClick={onNew}>New game</Button>
    </div>
  </div>
)

// The game's name over a side panel `width` wide: as large as the titles
// elsewhere, smaller when its longest word would not fit (a name of two
// words may take two lines).
export const Title = ({ ui, width, children }: any) => {
  const longest = Math.max(...String(children).split(' ').map((word) => word.length))
  const size = Math.floor(Math.min(ui.title, width / (longest * 0.6)))
  return <span className={`text-[${size}px] font-bold leading-tight`}>{children}</span>
}

// A round panel: the square inside the circle (`side`, at `x0`, `y0`), how
// wide a row may be whose far edge is `dy` px from the centre (`chord`), and
// where a round button `d` px wide sits along the rim, `deg` degrees from
// straight down (negative to the left), clear of a box `boxH` tall in the
// middle (`rimSpot`).
export const roundRoom = (W: number, H: number) => {
  const r = Math.min(W, H) / 2
  const inner = r - 12
  const side = Math.floor(inner * Math.SQRT2)
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, inner * inner - dy * dy)))
  const rimSpot = (d: number, boxH: number, toLeft: boolean) => {
    const ring = inner - d / 2 - 4
    const cos = Math.min(1, (boxH / 2 + 8 + d / 2) / ring)
    const sin = Math.sqrt(1 - cos * cos)
    return [Math.round(W / 2 + (toLeft ? -1 : 1) * ring * sin - d / 2), Math.round(H / 2 + ring * cos - d / 2)]
  }
  return { side, x0: (W - side) >> 1, y0: (H - side) >> 1, chord, rimSpot }
}

// A round button for the rim, an icon or a short word in it.
export const RimButton = ({ x, y, d, className, onClick, children }: any) => (
  <div className={`absolute left-[${x}px] top-[${y}px] w-[${d}px] h-[${d}px] rounded-full flex items-center justify-center ${className}`} onClick={onClick}>
    {children}
  </div>
)

export const SlidersGlyph = ({ px }: any) => (
  <svg viewBox="0 0 24 24" className={`w-[${px}px] h-[${px}px]`}>
    <line x1={3} y1={6} x2={21} y2={6} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <line x1={3} y1={12} x2={21} y2={12} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <line x1={3} y1={18} x2={21} y2={18} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <circle cx={8} cy={6} r={2.6} fill="currentColor" />
    <circle cx={16} cy={12} r={2.6} fill="currentColor" />
    <circle cx={10} cy={18} r={2.6} fill="currentColor" />
  </svg>
)

// The options page on a round panel: the title in the arc above, the rows in
// the square inside the circle (scrolling when they do not fit), Back and
// New game in the arc below.
const RoundOptionsPage = ({ ui, t, title, rows, onClose, onNew }: any) => {
  const { side, x0, y0, chord } = roundRoom(ui.W, ui.H)
  const titleSize = Math.max(16, Math.min(ui.big, Math.round(y0 * 0.36)))
  const bh = Math.max(40, Math.round(y0 * 0.55))
  // The rows stop short of the square's foot, so the buttons sit where the circle is wider.
  const listH = side - Math.round(bh / 2)
  const bTop = y0 + listH + Math.max(6, Math.round(y0 * 0.08))
  const bw = Math.floor((chord(bTop + bh - ui.H / 2) - ui.gap) / 2)
  const bFont = Math.max(14, Math.min(ui.text, Math.round(bh * 0.42), Math.round(bw / 5.4)))
  return (
    <div className={`relative w-[${ui.W}px] h-[${ui.H}px] ${t.page}`}>
      <div className={`absolute left-0 top-0 w-[${ui.W}px] h-[${y0 - Math.max(4, Math.round(y0 * 0.1))}px] flex items-end justify-center`}>
        <span className={`text-[${titleSize}px] font-bold leading-tight`}>{title}</span>
      </div>
      <div className={`absolute left-[${x0}px] top-[${y0}px] w-[${side}px] h-[${listH}px] overflow-y-auto`}>
        <div className={`flex flex-col gap-[${ui.gap}px]`}>
          {rows.map((row) =>
            row.min !== undefined ? (
              <Stepper ui={ui} t={t} label={row.label} value={row.value} min={row.min} max={row.max} step={row.step}
                onPick={(v) => frameos.setState(row.field, v)} />
            ) : (
              <Choice ui={ui} t={t} label={row.label} value={row.value} options={row.options}
                onPick={(v) => frameos.setState(row.field, v)} />
            ),
          )}
        </div>
      </div>
      <div className={`absolute left-0 top-[${bTop}px] w-[${ui.W}px] flex justify-center gap-[${ui.gap}px]`}>
        <div className={`w-[${bw}px] h-[${bh}px] rounded-xl flex items-center justify-center text-[${bFont}px] font-semibold ${t.button}`} onClick={onClose}>Back</div>
        <div className={`w-[${bw}px] h-[${bh}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${bFont}px] font-semibold ${t.primary}`} onClick={onNew}>New game</div>
      </div>
    </div>
  )
}
